  s.height = (rings * 0.30 * grain * (1.0 - clit) + striae * 0.14 + (anNoise(rp * 1900.0) - 0.5) * 0.04) * fine + seta * 0.9 + crumbs * low * 1.2 * mid - furrow * 0.5 * mid;
